static void require(bool ok,const char *message){if(!ok)throw std::runtime_error(message);}
static void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);}
static QByteArray read(const QString &p){QFile f(p);require(f.open(QIODevice::ReadOnly),"Syntax-color artifact missing");return f.readAll();}
static void write(const QString &p,const QByteArray &b){QFile f(p);require(f.open(QIODevice::WriteOnly)&&f.write(b)==b.size(),"Syntax-color artifact write failed");}
static bool blue(const QColor &c){const int h=c.hsvHue();return h>=205&&h<=245&&c.saturationF()>.25&&c.blue()>c.green()&&c.blue()>c.red();}
static int bluePixels(const QImage &image){int n=0;for(int y=0;y<image.height();++y)for(int x=0;x<image.width();++x){auto c=image.pixelColor(x,y);if(c.blue()>c.red()+12&&c.blue()>c.green()+6)++n;}return n;}
static QTextCharFormat formatAt(ScriptEditor &editor,int position){auto block=editor.document()->findBlock(position);const int offset=position-block.position();for(const auto &range:block.layout()->formats())if(range.start<=offset&&offset<range.start+range.length)return range.format;return {};}
